-- El primer fondo de caja es un aporte inicial. Los demás conteos pertenecen a sus turnos.
INSERT INTO asientos_contables (numero,fecha_hora,concepto,usuario_id)
SELECT printf('AS-%s-%04d',s.fecha,s.ultimo+1),t.apertura_fecha_hora,'Fondo inicial de caja',t.abierto_por_usuario_id
FROM turnos_caja t JOIN secuencias_folio s ON s.tipo='AS' AND s.fecha=replace(substr(t.apertura_fecha_hora,1,10),'-','')
WHERE t.id=1;
INSERT INTO asiento_detalles (asiento_id,cuenta_id,orden,debito_centavos,credito_centavos)
SELECT a.id,c.id,1,b.importe,0 FROM asientos_contables a, cuentas_contables c,
    (SELECT SUM(denominacion_centavos*cantidad) AS importe FROM conteos_caja WHERE turno_id=1 AND momento_id=1) b
WHERE a.concepto='Fondo inicial de caja' AND c.nombre='Caja';
INSERT INTO asiento_detalles (asiento_id,cuenta_id,orden,debito_centavos,credito_centavos)
SELECT a.id,c.id,2,0,b.importe FROM asientos_contables a, cuentas_contables c,
    (SELECT SUM(denominacion_centavos*cantidad) AS importe FROM conteos_caja WHERE turno_id=1 AND momento_id=1) b
WHERE a.concepto='Fondo inicial de caja' AND c.nombre='Patrimonio inicial';
UPDATE secuencias_folio SET ultimo=ultimo+1
WHERE tipo='AS' AND fecha=(SELECT replace(substr(apertura_fecha_hora,1,10),'-','') FROM turnos_caja WHERE id=1);

